fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    let maxsplit = maxsplit as usize; // Convert to usize for indexing
    a.into_iter()
        .map(|s| {
            if maxsplit == 0 {
                vec![s] // No splitting, return the original string
            } else {
                s.rsplitn(maxsplit + 1, &sep).map(String::from).collect() // Perform right split
            }
        })
        .collect() // Collect results into a vector
}